/**
 * Structured Output Generator
 *
 * Generates structured outputs from LLMs using JSON Schema mode.
 * Supports both OpenAI and compatible APIs.
 */

import { z } from 'zod';
import { zodToJsonSchema, wrapForOpenAI } from './schema-converter';
import type { StructuredOutputConfig, StructuredOutputOptions, StructuredOutputResult } from './types';

/**
 * Default configuration
 */
const DEFAULT_CONFIG: Partial<StructuredOutputConfig> = {
  baseUrl: 'https://api.openai.com/v1',
  model: 'gpt-4o-2024-08-06',
  temperature: 0,
  maxTokens: 4096,
};

/**
 * Generate structured output from an LLM
 *
 * @param options - Options including prompt and Zod schema
 * @param config - Provider configuration
 * @returns Parsed and validated result
 */
export async function generateStructuredOutput<T extends z.ZodType>(
  options: StructuredOutputOptions<T>,
  config: StructuredOutputConfig
): Promise<StructuredOutputResult<z.infer<T>>> {
  const mergedConfig = { ...DEFAULT_CONFIG, ...config, ...options.config };

  // Convert Zod schema to JSON Schema
  const jsonSchema = zodToJsonSchema(options.schema);

  // Wrap for OpenAI format
  const schemaName = options.schemaName ?? 'response';
  const responseFormat = wrapForOpenAI(jsonSchema, schemaName, options.schemaDescription);

  // Build messages
  const messages: Array<{ role: string; content: string }> = [];

  if (mergedConfig.systemPrompt) {
    messages.push({
      role: 'system',
      content: mergedConfig.systemPrompt,
    });
  }

  messages.push({
    role: 'user',
    content: options.prompt,
  });

  // Make request with retries
  const maxRetries = mergedConfig.retry?.maxRetries ?? 3;
  const initialDelay = mergedConfig.retry?.initialDelayMs ?? 1000;
  const maxDelay = mergedConfig.retry?.maxDelayMs ?? 10000;

  let lastError: Error | undefined;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const response = await fetch(`${mergedConfig.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${mergedConfig.apiKey}`,
        },
        body: JSON.stringify({
          model: mergedConfig.model,
          messages,
          response_format: responseFormat,
          temperature: mergedConfig.temperature,
          max_tokens: mergedConfig.maxTokens,
        }),
      });

      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(`API error: ${response.status} - ${errorBody}`);
      }

      const result = await response.json() as {
        choices: Array<{
          message: {
            content: string | null;
            refusal?: string | null;
          };
          finish_reason: string;
        }>;
        usage: {
          prompt_tokens: number;
          completion_tokens: number;
        };
      };

      const choice = result.choices[0];
      
      // Handle refusal
      if (choice.message.refusal) {
        return {
          data: undefined as unknown as z.infer<T>,
          raw: '',
          usage: {
            inputTokens: result.usage.prompt_tokens,
            outputTokens: result.usage.completion_tokens,
          },
          refusal: true,
          refusalMessage: choice.message.refusal,
        };
      }

      const rawContent = choice.message.content ?? '';

      // Parse JSON
      let parsed: unknown;
      try {
        parsed = JSON.parse(rawContent);
      } catch (parseError) {
        throw new Error(`Failed to parse JSON response: ${parseError}`);
      }

      // Validate with Zod
      const validated = options.schema.parse(parsed);

      return {
        data: validated,
        raw: rawContent,
        usage: {
          inputTokens: result.usage.prompt_tokens,
          outputTokens: result.usage.completion_tokens,
        },
        refusal: false,
      };
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      // Don't retry on validation errors
      if (lastError.message.includes('Failed to parse') || lastError.message.includes('Zod')) {
        throw lastError;
      }

      // Retry on retryable errors
      if (attempt < maxRetries) {
        const delay = Math.min(initialDelay * Math.pow(2, attempt), maxDelay);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError ?? new Error('Unknown error');
}

/**
 * Create a structured output generator with pre-configured settings
 */
export function createStructuredOutputGenerator(config: StructuredOutputConfig) {
  return {
    /**
     * Generate structured output
     */
    generate<T extends z.ZodType>(
      options: StructuredOutputOptions<T>
    ): Promise<StructuredOutputResult<z.infer<T>>> {
      return generateStructuredOutput(options, config);
    },

    /**
     * Simple helper for common use case
     */
    async extract<T extends z.ZodType>(
      prompt: string,
      schema: T,
      schemaName?: string
    ): Promise<z.infer<T>> {
      const result = await generateStructuredOutput(
        { prompt, schema, schemaName },
        config
      );
      
      if (result.refusal) {
        throw new Error(`Model refused to respond: ${result.refusalMessage}`);
      }
      
      return result.data;
    },
  };
}

/**
 * Generate structured output using the Responses API (for SAGE)
 * This version works with the OpenAI Responses API format
 */
export async function generateStructuredOutputResponses<T extends z.ZodType>(
  options: StructuredOutputOptions<T>,
  config: StructuredOutputConfig
): Promise<StructuredOutputResult<z.infer<T>>> {
  const mergedConfig = { ...DEFAULT_CONFIG, ...config, ...options.config };

  // Convert Zod schema to JSON Schema
  const jsonSchema = zodToJsonSchema(options.schema);
  const schemaName = options.schemaName ?? 'response';

  // Build input
  const input: Array<{ role: string; content: string }> = [
    {
      role: 'user',
      content: options.prompt,
    },
  ];

  // Make request
  const response = await fetch(`${mergedConfig.baseUrl}/responses`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${mergedConfig.apiKey}`,
      'OpenAI-Beta': 'responses=v1',
    },
    body: JSON.stringify({
      model: mergedConfig.model,
      instructions: mergedConfig.systemPrompt,
      input,
      text: {
        format: {
          type: 'json_schema',
          name: schemaName,
          description: options.schemaDescription,
          schema: jsonSchema,
          strict: true,
        },
      },
      temperature: mergedConfig.temperature,
      max_output_tokens: mergedConfig.maxTokens,
    }),
  });

  if (!response.ok) {
    const errorBody = await response.text();
    throw new Error(`Responses API error: ${response.status} - ${errorBody}`);
  }

  const result = await response.json() as {
    output: Array<{
      type: string;
      content?: string;
    }>;
    usage: {
      input_tokens: number;
      output_tokens: number;
    };
  };

  // Find the text output
  const textOutput = result.output.find(o => o.type === 'message');
  const rawContent = textOutput?.content ?? '';

  // Parse JSON
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawContent);
  } catch (parseError) {
    throw new Error(`Failed to parse JSON response: ${parseError}`);
  }

  // Validate with Zod
  const validated = options.schema.parse(parsed);

  return {
    data: validated,
    raw: rawContent,
    usage: {
      inputTokens: result.usage.input_tokens,
      outputTokens: result.usage.output_tokens,
    },
    refusal: false,
  };
}
