/**
 * JSON Parser with Validation
 *
 * Utilities for parsing and validating JSON against schemas.
 * Handles common edge cases like markdown code blocks and partial JSON.
 */

import { z } from 'zod';
import type { ParseResult } from './types';

/**
 * Extract JSON from a string that might contain markdown code blocks
 */
export function extractJson(input: string): string {
  // Try to find JSON in code blocks
  const codeBlockMatch = input.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
  if (codeBlockMatch) {
    return codeBlockMatch[1].trim();
  }

  // Try to find JSON object or array
  const jsonMatch = input.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
  if (jsonMatch) {
    return jsonMatch[1].trim();
  }

  // Return as-is
  return input.trim();
}

/**
 * Attempt to repair common JSON issues
 */
export function repairJson(input: string): string {
  let result = input;

  // Remove trailing commas before ] or }
  result = result.replace(/,(\s*[}\]])/g, '$1');

  // Fix unquoted keys (simple cases)
  result = result.replace(/([{,]\s*)([a-zA-Z_][a-zA-Z0-9_]*)(\s*:)/g, '$1"$2"$3');

  // Fix single quotes to double quotes (simple cases)
  result = result.replace(/'/g, '"');

  // Remove comments (// and /* */)
  result = result.replace(/\/\/.*$/gm, '');
  result = result.replace(/\/\*[\s\S]*?\*\//g, '');

  return result;
}

/**
 * Parse JSON string with automatic extraction and repair
 */
export function parseJson<T>(input: string): ParseResult<T> {
  // Extract JSON from potential markdown
  let jsonStr = extractJson(input);

  // First attempt: parse directly
  try {
    const data = JSON.parse(jsonStr) as T;
    return { success: true, data };
  } catch {
    // Continue to repair attempt
  }

  // Second attempt: repair and parse
  try {
    jsonStr = repairJson(jsonStr);
    const data = JSON.parse(jsonStr) as T;
    return { success: true, data };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to parse JSON',
    };
  }
}

/**
 * Parse and validate JSON against a Zod schema
 */
export function parseAndValidate<T extends z.ZodType>(
  input: string,
  schema: T
): ParseResult<z.infer<T>> {
  // Parse JSON first
  const parseResult = parseJson<unknown>(input);
  if (!parseResult.success) {
    return parseResult as ParseResult<z.infer<T>>;
  }

  // Validate with Zod
  const validationResult = schema.safeParse(parseResult.data);

  if (validationResult.success) {
    return {
      success: true,
      data: validationResult.data,
    };
  }

  // Format Zod errors
  const issues = validationResult.error.issues.map(issue => ({
    path: issue.path,
    message: issue.message,
  }));

  return {
    success: false,
    error: `Validation failed: ${issues.map(i => `${i.path.join('.')}: ${i.message}`).join('; ')}`,
    issues,
  };
}

/**
 * Strictly parse JSON (no repair, no extraction)
 */
export function parseJsonStrict<T>(input: string): ParseResult<T> {
  try {
    const data = JSON.parse(input) as T;
    return { success: true, data };
  } catch (error) {
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Failed to parse JSON',
    };
  }
}

/**
 * Parse JSON with a fallback default value
 */
export function parseJsonWithDefault<T>(input: string, defaultValue: T): T {
  const result = parseJson<T>(input);
  return result.success ? result.data! : defaultValue;
}

/**
 * Check if a string is valid JSON
 */
export function isValidJson(input: string): boolean {
  try {
    JSON.parse(input);
    return true;
  } catch {
    return false;
  }
}

/**
 * Safely stringify an object to JSON with error handling
 */
export function safeStringify(value: unknown, indent?: number): string {
  try {
    return JSON.stringify(value, null, indent);
  } catch (error) {
    // Handle circular references
    const seen = new WeakSet();
    return JSON.stringify(value, (_, val) => {
      if (typeof val === 'object' && val !== null) {
        if (seen.has(val)) {
          return '[Circular]';
        }
        seen.add(val);
      }
      return val;
    }, indent);
  }
}
