/**
 * Schema Converter
 *
 * Converts Zod schemas to JSON Schema for use with OpenAI's structured outputs.
 * Handles common Zod types and produces OpenAI-compatible JSON Schema.
 */

import { z } from 'zod';
import type { JSONSchema } from './types';

// Access internal Zod definitions
type ZodDef = z.ZodTypeDef & { typeName?: string; checks?: Array<{ kind: string; value?: number; regex?: RegExp }> };

/**
 * Convert a Zod schema to JSON Schema
 */
export function zodToJsonSchema(schema: z.ZodType, definitions?: Map<string, JSONSchema>): JSONSchema {
  const defs = definitions ?? new Map<string, JSONSchema>();
  const result = convertZodType(schema, defs);
  
  // Add definitions if any were collected
  if (defs.size > 0) {
    const $defs: Record<string, JSONSchema> = {};
    for (const [name, def] of defs) {
      $defs[name] = def;
    }
    return { ...result, $defs };
  }
  
  return result;
}

/**
 * Get the Zod type name from a schema
 */
function getTypeName(schema: z.ZodType): string {
  return (schema._def as ZodDef).typeName ?? 'unknown';
}

/**
 * Convert a Zod type to JSON Schema
 */
function convertZodType(schema: z.ZodType, definitions: Map<string, JSONSchema>): JSONSchema {
  const typeName = getTypeName(schema);
  
  switch (typeName) {
    case 'ZodString':
      return convertZodString(schema as z.ZodString);
    
    case 'ZodNumber':
      return convertZodNumber(schema as z.ZodNumber);
    
    case 'ZodBoolean':
      return { type: 'boolean' };
    
    case 'ZodNull':
      return { type: 'null' };
    
    case 'ZodArray':
      return convertZodArray(schema as z.ZodArray<z.ZodType>, definitions);
    
    case 'ZodObject':
      return convertZodObject(schema as z.ZodObject<z.ZodRawShape>, definitions);
    
    case 'ZodEnum':
      return convertZodEnum(schema as z.ZodEnum<[string, ...string[]]>);
    
    case 'ZodNativeEnum':
      return convertZodNativeEnum(schema);
    
    case 'ZodLiteral':
      return convertZodLiteral(schema as z.ZodLiteral<unknown>);
    
    case 'ZodUnion':
      return convertZodUnion(schema as z.ZodUnion<[z.ZodType, ...z.ZodType[]]>, definitions);
    
    case 'ZodDiscriminatedUnion':
      return convertZodDiscriminatedUnion(schema, definitions);
    
    case 'ZodOptional':
      return convertZodType((schema as z.ZodOptional<z.ZodType>).unwrap(), definitions);
    
    case 'ZodNullable':
      return convertZodNullable(schema as z.ZodNullable<z.ZodType>, definitions);
    
    case 'ZodDefault':
      return convertZodDefault(schema as z.ZodDefault<z.ZodType>, definitions);
    
    case 'ZodEffects':
      // Effects (refine, transform) - use inner type
      return convertZodType((schema as z.ZodEffects<z.ZodType>).innerType(), definitions);
    
    case 'ZodRecord':
      return convertZodRecord(schema as z.ZodRecord<z.ZodString, z.ZodType>, definitions);
    
    case 'ZodTuple':
      return convertZodTuple(schema as z.ZodTuple<[z.ZodType, ...z.ZodType[]]>, definitions);
    
    case 'ZodLazy':
      // Lazy schemas need special handling for recursion
      return convertZodType((schema as z.ZodLazy<z.ZodType>).schema, definitions);
    
    case 'ZodAny':
    case 'ZodUnknown':
      return {}; // Any valid JSON
    
    case 'ZodNever':
      return { not: {} }; // Never matches anything
    
    default:
      // Fallback: treat as any
      console.warn(`[SchemaConverter] Unknown Zod type: ${typeName}, treating as any`);
      return {};
  }
}

/**
 * Convert ZodString with constraints
 */
function convertZodString(schema: z.ZodString): JSONSchema {
  const result: JSONSchema = { type: 'string' };
  
  const checks = (schema._def as ZodDef).checks || [];
  for (const check of checks) {
    switch (check.kind) {
      case 'min':
        result.minLength = check.value;
        break;
      case 'max':
        result.maxLength = check.value;
        break;
      case 'length':
        result.minLength = check.value;
        result.maxLength = check.value;
        break;
      case 'email':
        result.format = 'email';
        break;
      case 'url':
        result.format = 'uri';
        break;
      case 'uuid':
        result.format = 'uuid';
        break;
      case 'datetime':
        result.format = 'date-time';
        break;
      case 'date':
        result.format = 'date';
        break;
      case 'time':
        result.format = 'time';
        break;
      case 'regex':
        if (check.regex) {
          result.pattern = check.regex.source;
        }
        break;
    }
  }
  
  return result;
}

/**
 * Convert ZodNumber with constraints
 */
function convertZodNumber(schema: z.ZodNumber): JSONSchema {
  const checks = (schema._def as ZodDef).checks || [];
  const isInt = checks.some(c => c.kind === 'int');
  const result: JSONSchema = { type: isInt ? 'integer' : 'number' };
  
  for (const check of checks) {
    switch (check.kind) {
      case 'min':
        result.minimum = check.value;
        break;
      case 'max':
        result.maximum = check.value;
        break;
    }
  }
  
  return result;
}

/**
 * Convert ZodArray
 */
function convertZodArray(schema: z.ZodArray<z.ZodType>, definitions: Map<string, JSONSchema>): JSONSchema {
  return {
    type: 'array',
    items: convertZodType(schema.element, definitions),
  };
}

/**
 * Convert ZodObject
 */
function convertZodObject(schema: z.ZodObject<z.ZodRawShape>, definitions: Map<string, JSONSchema>): JSONSchema {
  const shape = schema.shape;
  const properties: Record<string, JSONSchema> = {};
  const required: string[] = [];
  
  for (const [key, value] of Object.entries(shape)) {
    const zodValue = value as z.ZodType;
    properties[key] = convertZodType(zodValue, definitions);
    
    // Add description from Zod
    if (zodValue.description) {
      properties[key].description = zodValue.description;
    }
    
    // Check if required (not optional)
    if (!isZodOptional(zodValue)) {
      required.push(key);
    }
  }
  
  const result: JSONSchema = {
    type: 'object',
    properties,
    additionalProperties: false, // OpenAI structured outputs require this
  };
  
  if (required.length > 0) {
    result.required = required;
  }
  
  return result;
}

/**
 * Check if a Zod type is optional
 */
function isZodOptional(schema: z.ZodType): boolean {
  const typeName = getTypeName(schema);
  
  if (typeName === 'ZodOptional') return true;
  if (typeName === 'ZodDefault') return true;
  if (typeName === 'ZodNullable') {
    // Nullable alone doesn't make it optional for required fields
    return false;
  }
  
  return false;
}

/**
 * Convert ZodEnum
 */
function convertZodEnum(schema: z.ZodEnum<[string, ...string[]]>): JSONSchema {
  return {
    type: 'string',
    enum: schema.options as string[],
  };
}

/**
 * Convert ZodNativeEnum
 */
function convertZodNativeEnum(schema: z.ZodType): JSONSchema {
  // Access the enum object from the schema definition
  const enumObj = (schema._def as { values?: unknown[] }).values;
  if (!enumObj || !Array.isArray(enumObj)) {
    return { type: 'string' };
  }
  
  const isStringEnum = enumObj.every(v => typeof v === 'string');
  
  if (isStringEnum) {
    return {
      type: 'string',
      enum: enumObj as string[],
    };
  }
  
  // Mixed or number enum
  return { enum: enumObj as (string | number)[] };
}

/**
 * Convert ZodLiteral
 */
function convertZodLiteral(schema: z.ZodLiteral<unknown>): JSONSchema {
  const value = schema.value;
  
  if (typeof value === 'string') {
    return { type: 'string', const: value };
  }
  if (typeof value === 'number') {
    return { type: 'number', const: value };
  }
  if (typeof value === 'boolean') {
    return { type: 'boolean', const: value };
  }
  if (value === null) {
    return { type: 'null' };
  }
  
  return { const: value };
}

/**
 * Convert ZodUnion
 */
function convertZodUnion(schema: z.ZodUnion<[z.ZodType, ...z.ZodType[]]>, definitions: Map<string, JSONSchema>): JSONSchema {
  const options = schema.options.map(opt => convertZodType(opt, definitions));
  return { anyOf: options };
}

/**
 * Convert ZodDiscriminatedUnion
 */
function convertZodDiscriminatedUnion(
  schema: z.ZodType,
  definitions: Map<string, JSONSchema>
): JSONSchema {
  // Access options from the discriminated union definition
  const def = schema._def as { options?: z.ZodType[] };
  if (!def.options) {
    return {};
  }
  const options = def.options.map(opt => convertZodType(opt, definitions));
  return { oneOf: options };
}

/**
 * Convert ZodNullable
 */
function convertZodNullable(schema: z.ZodNullable<z.ZodType>, definitions: Map<string, JSONSchema>): JSONSchema {
  const inner = convertZodType(schema.unwrap(), definitions);
  return { anyOf: [inner, { type: 'null' }] };
}

/**
 * Convert ZodDefault
 */
function convertZodDefault(schema: z.ZodDefault<z.ZodType>, definitions: Map<string, JSONSchema>): JSONSchema {
  const inner = convertZodType(schema._def.innerType, definitions);
  return {
    ...inner,
    default: schema._def.defaultValue(),
  };
}

/**
 * Convert ZodRecord
 */
function convertZodRecord(schema: z.ZodRecord<z.ZodString, z.ZodType>, definitions: Map<string, JSONSchema>): JSONSchema {
  return {
    type: 'object',
    additionalProperties: convertZodType(schema.valueSchema, definitions),
  };
}

/**
 * Convert ZodTuple
 */
function convertZodTuple(schema: z.ZodTuple<[z.ZodType, ...z.ZodType[]]>, definitions: Map<string, JSONSchema>): JSONSchema {
  const items = schema.items.map(item => convertZodType(item, definitions));
  return {
    type: 'array',
    items: items.length === 1 ? items[0] : items,
  };
}

/**
 * Wrap a JSON Schema for OpenAI's structured outputs format
 */
export function wrapForOpenAI(
  schema: JSONSchema,
  name: string,
  description?: string
): {
  type: 'json_schema';
  json_schema: {
    name: string;
    description?: string;
    schema: JSONSchema;
    strict: true;
  };
} {
  return {
    type: 'json_schema',
    json_schema: {
      name,
      description,
      schema,
      strict: true,
    },
  };
}
